51	/**
52	 * 屠宰检疫业务服务：申报→宰前检疫→同步检验→判定分流→出厂核销。
53	 * 申报、检验与回执登记均以 requestId 幂等；判定分流与库存标识在同一事务内完成。
54	 */
55	@Service
56	public class BatchService {
57	
58	    private static final Logger log = LoggerFactory.getLogger(BatchService.class);
59	
60	    /** 宰前检疫有效期：自申报起 6 小时（UTC），恰满 6 小时即失效须重新申报。 */
61	    static final Duration QUARANTINE_VALIDITY = Duration.ofHours(6);
62	
63	    private final BatchRepository repo;
64	    private final Clock clock;
65	    private final ObjectMapper objectMapper;
66	    /** 漏检暂停独立事务：判定请求整体回滚时，暂停状态仍须落库。 */
67	    private final TransactionTemplate pauseTemplate;
68	
69	    public BatchService(BatchRepository repo, Clock clock, ObjectMapper objectMapper,
70	                        PlatformTransactionManager transactionManager) {
71	        this.repo = repo;
72	        this.clock = clock;
73	        this.objectMapper = objectMapper;
74	        this.pauseTemplate = new TransactionTemplate(transactionManager);
75	        this.pauseTemplate.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);
76	    }
77	
78	    // ---------- 宰前申报 ----------
79	
80	    /**
81	     * 宰前申报：新批次建档并建立头只台账；批次已存在且 6 小时有效期恰满/已过且未进入后续环节时，
82	     * 视为重新申报，重置申报时间与头只台账；其余情况拒绝。
83	     */
84	    @Transactional
85	    public DeclareResponse declare(DeclareRequest req) {
86	        return idempotent("declare", req.requestId(), req, DeclareResponse.class, () -> doDeclare(req));
87	    }
88	
89	    private DeclareResponse doDeclare(DeclareRequest req) {
90	        validateDistinctHeadNos(req.headNos());
91	        String now = now();
92	        Optional<BatchRow> existing = repo.findBatchByNo(req.batchNo());
93	        if (existing.isEmpty()) {
94	            repo.insertBatch(req.batchNo(), req.species(), req.farmOrigin(), req.headNos().size(),
95	                    BatchStatus.DECLARED.name(), now, now);
96	            BatchRow batch = mustFind(req.batchNo());
97	            insertHeads(batch.id(), req.headNos(), now);
98	            return new DeclareResponse(batch.batchNo(), batch.status(), now, req.headNos().size());
99	        }
100	        BatchRow batch = existing.get();
101	        if (!BatchStatus.DECLARED.name().equals(batch.status())) {
102	            throw ApiException.conflict("批次已进入后续环节，不允许重新申报");
103	        }
104	        Instant declaredAt = Instant.parse(batch.declaredAt());
105	        if (Instant.now(clock).isBefore(declaredAt.plus(QUARANTINE_VALIDITY))) {
106	            throw ApiException.conflict("批次已申报且仍在宰前检疫 6 小时有效期内");
107	        }
108	        repo.resetForRedeclare(batch.id(), req.species(), req.farmOrigin(), req.headNos().size(), now);
109	        repo.deleteHeads(batch.id());
110	        insertHeads(batch.id(), req.headNos(), now);
111	        return new DeclareResponse(batch.batchNo(), BatchStatus.DECLARED.name(), now, req.headNos().size());
112	    }
113	
114	    // ---------- 宰前检疫 ----------
115	
116	    /**
117	     * 宰前检疫：自申报起 6 小时内（UTC）有效，恰满 6 小时未屠宰须重新申报。
118	     * 同一批次同时刻只允许一条检验链（DECLARED→PRE_QUARANTINED 条件流转保证）。
119	     */
120	    @Transactional
121	    public PreQuarantineResponse preQuarantine(String batchNo, PreQuarantineRequest req) {
122	        return idempotent("pre-quarantine", req.requestId(), req, PreQuarantineResponse.class,
123	                () -> doPreQuarantine(batchNo));
124	    }
125	
126	    private PreQuarantineResponse doPreQuarantine(String batchNo) {
127	        BatchRow batch = mustFind(batchNo);
128	        if (!BatchStatus.DECLARED.name().equals(batch.status())) {
129	            throw ApiException.conflict("批次当前状态不允许宰前检疫");
130	        }
131	        Instant nowInstant = Instant.now(clock);
132	        Instant deadline = Instant.parse(batch.declaredAt()).plus(QUARANTINE_VALIDITY);
133	        if (!nowInstant.isBefore(deadline)) {
134	            throw ApiException.unprocessable("宰前检疫已超过申报后 6 小时有效期，须重新申报");
135	        }
136	        String now = nowInstant.toString();
137	        int updated = repo.markPreQuarantined(batch.id(), now);
138	        if (updated == 0) {
139	            throw ApiException.conflict("并发检疫冲突：同一批次同时刻只允许一条检验链");
140	        }
141	        return new PreQuarantineResponse(batchNo, BatchStatus.PRE_QUARANTINED.name(), now);
142	    }
143	
144	    // ---------- 同步检验 ----------
145	
146	    /**
147	     * 同步检验：按头只编号一一对应登记；漏检头只将在判定分流时导致整批暂停流转。
148	     */
149	    @Transactional
150	    public InspectionResponse inspect(String batchNo, InspectionRequest req) {
151	        return idempotent("inspection", req.requestId(), req, InspectionResponse.class,
152	                () -> doInspect(batchNo, req));
153	    }
154	
155	    private InspectionResponse doInspect(String batchNo, InspectionRequest req) {
156	        BatchRow batch = mustFind(batchNo);
157	        String status = batch.status();
158	        boolean inspectable = BatchStatus.PRE_QUARANTINED.name().equals(status)
159	                || BatchStatus.INSPECTING.name().equals(status)
160	                || BatchStatus.PAUSED.name().equals(status);
161	        if (!inspectable) {
162	            throw ApiException.conflict("批次当前状态不允许同步检验");
163	        }
164	        repo.findHead(batch.id(), req.headNo())
165	                .orElseThrow(() -> ApiException.notFound("头只编号不存在：" + req.headNo()));
166	        int updated = repo.markHeadInspected(batch.id(), req.headNo(), req.result(), now());
167	        if (updated == 0) {
168	            throw ApiException.conflict("头只已完成同步检验，重复检验须使用原 requestId 重放");
169	        }
170	        if (BatchStatus.PRE_QUARANTINED.name().equals(status)) {
171	            repo.transitionStatus(batch.id(), List.of(BatchStatus.PRE_QUARANTINED.name()),
172	                    BatchStatus.INSPECTING.name());
173	        }
174	        int inspected = repo.countInspectedHeads(batch.id());
175	        return new InspectionResponse(batchNo, req.headNo(), "INSPECTED", inspected, batch.headCount());
176	    }
177	
178	    // ---------- 判定分流 ----------
179	
180	    /**
181	     * 判定分流：合格/有条件食用/化制/销毁四类；判定与库存标识在同一事务内完成。
182	     * 存在漏检头只时整批暂停流转并拒绝判定。
183	     */
184	    @Transactional
185	    public JudgmentResponse judge(String batchNo, JudgmentRequest req) {
186	        return idempotent("judgment", req.requestId(), req, JudgmentResponse.class,
187	                () -> doJudge(batchNo, req));
188	    }
189	
190	    private JudgmentResponse doJudge(String batchNo, JudgmentRequest req) {
191	        BatchRow batch = mustFind(batchNo);
192	        String status = batch.status();
193	        boolean judgeable = BatchStatus.PRE_QUARANTINED.name().equals(status)
194	                || BatchStatus.INSPECTING.name().equals(status)
195	                || BatchStatus.PAUSED.name().equals(status);
196	        if (!judgeable) {
197	            throw ApiException.conflict("批次当前状态不允许判定分流");
198	        }
199	        List<HeadRow> heads = repo.findHeads(batch.id());
200	        List<String> missing = heads.stream()
201	                .filter(h -> "PENDING".equals(h.status()))
202	                .map(HeadRow::headNo)
203	                .toList();
204	        if (!missing.isEmpty()) {
205	            // 独立事务落库暂停状态：判定请求本身回滚，整批暂停仍然生效
206	            pauseTemplate.executeWithoutResult(s -> repo.transitionStatus(batch.id(),
207	                    List.of(BatchStatus.PRE_QUARANTINED.name(), BatchStatus.INSPECTING.name(),
208	                            BatchStatus.PAUSED.name()),
209	                    BatchStatus.PAUSED.name()));
210	            throw ApiException.conflict("存在漏检头只 " + missing + "，整批暂停流转");
211	        }
212	        Map<String, HeadRow> byHeadNo = new LinkedHashMap<>();
213	        for (HeadRow head : heads) {
214	            byHeadNo.put(head.headNo(), head);
215	        }
216	        Set<String> covered = new HashSet<>();
217	        List<ResolvedJudgment> resolved = new ArrayList<>();
218	        for (JudgmentRequest.JudgmentItem item : req.judgments()) {
219	            if (!byHeadNo.containsKey(item.headNo())) {
220	                throw ApiException.unprocessable("判定包含批次外头只：" + item.headNo());
221	            }
222	            if (!covered.add(item.headNo())) {
223	                throw ApiException.unprocessable("判定包含重复头只：" + item.headNo());
224	            }
225	            resolved.add(resolve(item));
226	        }
227	        if (covered.size() != heads.size()) {
228	            throw ApiException.unprocessable("判定须覆盖批次全部头只，缺 "
229	                    + (heads.size() - covered.size()) + " 头");
230	        }
231	        String now = now();
232	        Map<String, Integer> counts = new LinkedHashMap<>();
233	        for (ResolvedJudgment r : resolved) {
234	            boolean qualified = r.category() == JudgmentCategory.QUALIFIED;
235	            boolean conditional = r.category() == JudgmentCategory.CONDITIONAL;
236	            repo.insertJudgment(batch.id(), r.headNo(), r.category().name(),
237	                    conditional && Boolean.TRUE.equals(r.highTemp()),
238	                    conditional ? r.circulationArea() : null, now);
239	            repo.applyJudgment(batch.id(), r.headNo(), r.category().name(),
240	                    conditional ? r.highTemp() : null,
241	                    conditional ? r.circulationArea() : null,
242	                    qualified, now);
243	            counts.merge(r.category().name(), 1, Integer::sum);
244	        }
245	        repo.markJudged(batch.id(), now);
246	        return new JudgmentResponse(batchNo, BatchStatus.JUDGED.name(), resolved.size(), counts);
247	    }
248	
249	    /** 单头只判定项解析结果。 */
250	    private record ResolvedJudgment(String headNo, JudgmentCategory category, Boolean highTemp,
251	                                    String circulationArea) {
252	    }
253	
254	    private ResolvedJudgment resolve(JudgmentRequest.JudgmentItem item) {
255	        JudgmentCategory category = parseCategory(item.category());
256	        if (category == JudgmentCategory.CONDITIONAL
257	                && (!Boolean.TRUE.equals(item.highTemp())
258	                || item.circulationArea() == null || item.circulationArea().isBlank())) {
259	            throw ApiException.unprocessable("有条件食用须标注高温处理并限定流通区域");
260	        }
261	        return new ResolvedJudgment(item.headNo(), category, item.highTemp(), item.circulationArea());
262	    }
263	
264	    // ---------- 无害化处理回执 ----------
265	
266	    /**
267	     * 回执登记：化制/销毁须取得无害化处理回执闭环；批次已核销时回执按迟到处理，
268	     * 只记迟到事件并告警，不改变批次状态。
269	     */
270	    @Transactional
271	    public ReceiptResponse registerReceipt(String batchNo, ReceiptRequest req) {
272	        return idempotent("receipt", req.requestId(), req, ReceiptResponse.class,
273	                () -> doRegisterReceipt(batchNo, req));
274	    }
275	
276	    private ReceiptResponse doRegisterReceipt(String batchNo, ReceiptRequest req) {
277	        BatchRow batch = mustFind(batchNo);
278	        JudgmentCategory category = parseCategory(req.category());
279	        if (category != JudgmentCategory.RENDERING && category != JudgmentCategory.DESTRUCTION) {
280	            throw ApiException.unprocessable("无害化处理回执仅支持化制（RENDERING）与销毁（DESTRUCTION）类别");
281	        }
282	        String now = now();
283	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
284	            repo.insertReceipt(batch.id(), req.receiptNo(), category.name(), req.headCount(),
285	                    req.processor(), true, now);
286	            repo.insertLateEvent(batch.id(), "LATE_RECEIPT",
287	                    "核销后迟到回执 " + req.receiptNo() + "，类别 " + category.name()
288	                            + "，头只数 " + req.headCount(),
289	                    now);
290	            log.warn("批次 {} 已出厂核销，回执 {} 迟到登记并告警", batchNo, req.receiptNo());
291	            return new ReceiptResponse(batchNo, req.receiptNo(), category.name(), req.headCount(),
292	                    true, reconciliation(batch.id()));
293	        }
294	        if (!BatchStatus.JUDGED.name().equals(batch.status())) {
295	            throw ApiException.conflict("批次未完成判定分流，不允许登记无害化处理回执");
296	        }
297	        repo.insertReceipt(batch.id(), req.receiptNo(), category.name(), req.headCount(),
298	                req.processor(), false, now);
299	        return new ReceiptResponse(batchNo, req.receiptNo(), category.name(), req.headCount(),
300	                false, reconciliation(batch.id()));
301	    }
302	
303	    // ---------- 出厂核销 ----------
304	
305	    /**
306	     * 出厂核销：回执头只数与判定数恰等受理、不等拒绝；核销为终态，重复核销返回幂等成功。
307	     */
308	    @Transactional
309	    public ReleaseResponse release(String batchNo, ReleaseRequest req) {
310	        return idempotent("release", req.requestId(), req, ReleaseResponse.class,
311	                () -> doRelease(batchNo));
312	    }
313	
314	    private ReleaseResponse doRelease(String batchNo) {
315	        BatchRow batch = mustFind(batchNo);
316	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
317	            return new ReleaseResponse(batchNo, BatchStatus.RELEASED.name(), batch.releasedAt(),
318	                    reconciliation(batch.id()));
319	        }
320	        if (!BatchStatus.JUDGED.name().equals(batch.status())) {
321	            throw ApiException.conflict("批次未达到可核销状态");
322	        }
323	        List<ReconciliationEntry> reconciliation = reconciliation(batch.id());
324	        List<String> mismatched = reconciliation.stream()
325	                .filter(e -> !e.matched())
326	                .map(e -> e.category() + "(判定 " + e.judgedCount() + " / 回执 " + e.receivedCount() + ")")
327	                .toList();
328	        if (!mismatched.isEmpty()) {
329	            throw ApiException.conflict("回执头只数与判定数不一致，拒绝出厂：" + mismatched);
330	        }
331	        String now = now();
332	        int updated = repo.markReleased(batch.id(), now);
333	        if (updated == 0) {
334	            throw ApiException.conflict("并发核销冲突");
335	        }
336	        return new ReleaseResponse(batchNo, BatchStatus.RELEASED.name(), now, reconciliation);
337	    }
338	
339	    // ---------- 批次视图 ----------
340	
341	    /**
342	     * 批次全量视图：头只台账、判定明细与回执勾稽均可由明细复算。
343	     */
344	    @Transactional(readOnly = true)
345	    public BatchView getView(String batchNo) {
346	        BatchRow batch = mustFind(batchNo);
347	        List<BatchView.HeadView> heads = repo.findHeads(batch.id()).stream()
348	                .map(h -> new BatchView.HeadView(h.headNo(), h.status(), h.inspectionResult(),
349	                        h.judgmentCategory(), h.highTemp(), h.circulationArea(), h.inventoryMarked()))
350	                .toList();
351	        List<BatchView.JudgmentView> judgments = repo.findJudgments(batch.id()).stream()
352	                .map(j -> new BatchView.JudgmentView(j.headNo(), j.category(), j.highTemp(),
353	                        j.circulationArea()))
354	                .toList();
355	        List<BatchView.ReceiptView> receipts = repo.findReceipts(batch.id()).stream()
356	                .map(r -> new BatchView.ReceiptView(r.receiptNo(), r.category(), r.headCount(),
357	                        r.processor(), r.late(), r.receivedAt()))
358	                .toList();
359	        List<BatchView.LateEventView> lateEvents = repo.findLateEvents(batch.id()).stream()
360	                .map(e -> new BatchView.LateEventView(e.eventType(), e.detail(), e.createdAt()))
361	                .toList();
362	        return new BatchView(batch.batchNo(), batch.status(), batch.species(), batch.farmOrigin(),
363	                batch.declaredAt(), batch.preQuarantinedAt(), batch.judgedAt(), batch.releasedAt(),
364	                heads, judgments, receipts, lateEvents, reconciliation(batch.id()));
365	    }
366	
367	    // ---------- 内部：勾稽 / 幂等 / 工具 ----------
368	
369	    /** 回执勾稽：按化制/销毁类别对比判定头只数与已登记回执头只数（不含迟到回执），恰等一致。 */
370	    private List<ReconciliationEntry> reconciliation(long batchId) {
371	        List<JudgmentRow> judgments = repo.findJudgments(batchId);
372	        List<ReceiptRow> receipts = repo.findReceipts(batchId);
373	        List<ReconciliationEntry> entries = new ArrayList<>();
374	        for (JudgmentCategory category : List.of(JudgmentCategory.RENDERING, JudgmentCategory.DESTRUCTION)) {
375	            int judged = (int) judgments.stream()
376	                    .filter(j -> category.name().equals(j.category()))
377	                    .count();
378	            int received = receipts.stream()
379	                    .filter(r -> category.name().equals(r.category()) && !r.late())
380	                    .mapToInt(ReceiptRow::headCount)
381	                    .sum();
382	            entries.add(new ReconciliationEntry(category.name(), judged, received, judged == received));
383	        }
384	        return entries;
385	    }
386	
387	    /**
388	     * 幂等受理：指纹覆盖 requestId 与全部业务字段；同键同参返回首次结果，同键异参返回 409 且不改变批次状态。
389	     * 并发下同键请求依赖 requestId 全局唯一约束，仅首次受理成功，其余重放首次结果。
390	     */
391	    private <T> T idempotent(String endpoint, String requestId, Object request, Class<T> type,
392	                             Supplier<T> action) {
393	        String fingerprint = fingerprint(requestId, request);
394	        Optional<IdempotencyRow> existing = repo.findIdempotency(requestId);
395	        if (existing.isPresent()) {
396	            IdempotencyRow record = existing.get();
397	            if (!record.fingerprint().equals(fingerprint)) {
398	                throw ApiException.conflict("相同 requestId 携带不同业务参数，拒绝受理");
399	            }
400	            return readValue(record.responseBody(), type);
401	        }
402	        try {
403	            T result = action.get();
404	            repo.insertIdempotency(requestId, endpoint, fingerprint, writeValue(result), now());
405	            return result;
406	        } catch (DuplicateKeyException e) {
407	            Optional<IdempotencyRow> concurrent = repo.findIdempotency(requestId);
408	            if (concurrent.isPresent() && concurrent.get().fingerprint().equals(fingerprint)) {
409	                return readValue(concurrent.get().responseBody(), type);
410	            }
411	            throw ApiException.conflict("并发受理冲突：批次或请求标识已被其他请求占用");
412	        }
413	    }
414	
415	    private String fingerprint(String requestId, Object request) {
416	        try {
417	            String json = objectMapper.writeValueAsString(request);
418	            MessageDigest digest = MessageDigest.getInstance("SHA-256");
419	            byte[] hash = digest.digest(
420	                    (requestId + "\n" + json).getBytes(StandardCharsets.UTF_8));
421	            StringBuilder hex = new StringBuilder(hash.length * 2);
422	            for (byte b : hash) {
423	                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
424	                hex.append(Character.forDigit(b & 0xF, 16));
425	            }
426	            return hex.toString();
427	        } catch (Exception e) {
428	            throw new IllegalStateException("请求指纹计算失败", e);
429	        }
430	    }
431	
432	    private <T> T readValue(String json, Class<T> type) {
433	        try {
434	            return objectMapper.readValue(json, type);
435	        } catch (Exception e) {
436	            throw new IllegalStateException("幂等响应反序列化失败", e);
437	        }
438	    }
439	
440	    private String writeValue(Object value) {
441	        try {
442	            return objectMapper.writeValueAsString(value);
443	        } catch (Exception e) {
444	            throw new IllegalStateException("幂等响应序列化失败", e);
445	        }
446	    }
447	
448	    private BatchRow mustFind(String batchNo) {
449	        return repo.findBatchByNo(batchNo)
450	                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
451	    }
452	
453	    private JudgmentCategory parseCategory(String category) {
454	        try {
455	            return JudgmentCategory.valueOf(category);
456	        } catch (Exception e) {
457	            throw ApiException.unprocessable("未知判定类别：" + category
458	                    + "，支持 QUALIFIED/CONDITIONAL/RENDERING/DESTRUCTION");
459	        }
460	    }
461	
462	    private void validateDistinctHeadNos(List<String> headNos) {
463	        Set<String> seen = new HashSet<>();
464	        for (String headNo : headNos) {
465	            if (!seen.add(headNo)) {
466	                throw ApiException.unprocessable("头只编号重复：" + headNo);
467	            }
468	        }
469	    }
470	
471	    private void insertHeads(long batchId, List<String> headNos, String now) {
472	        for (String headNo : headNos) {
473	            repo.insertHead(batchId, headNo, "PENDING", now);
474	        }
475	    }
476	
477	    private String now() {
478	        return Instant.now(clock).toString();
479	    }
480	}
