37	    void quarantineWindowExactlySixHours() throws Exception {
38	        // 恰满前 1 秒：检疫有效
39	        declareOk("d-1", "B-6H-1", List.of("H1"));
40	        clock.set(TestClockConfig.T0.plus(SIX_HOURS).minusSeconds(1));
