65	        clock.set(TestClockConfig.T0.plus(Duration.ofHours(3)));
66	        postJson("/api/batches/declare",
67	                new DeclareRequest("d-2", "B-RED", "PIG", "合成养殖场", List.of("H1")))
68	                .andExpect(status().isConflict());
