package com.example.starter.domain;

/**
 * 合成风险等级：普通抽检 10%、加严抽检 30%，数量为头只数乘比例向上取整且至少 1。
 */
public enum RiskLevel {
    /** 普通，抽检比例 10%。 */
    NORMAL(10),
    /** 加严，抽检比例 30%。 */
    STRICT(30);

    private final int ratioPercent;

    RiskLevel(int ratioPercent) {
        this.ratioPercent = ratioPercent;
    }

    /** 抽检比例（百分数）。 */
    public int ratioPercent() {
        return ratioPercent;
    }

    /**
     * 冻结抽样数量：headCount 乘比例向上取整且至少 1。
     *
     * @param headCount 批次头只数
     * @return 抽样数量
     */
    public int sampleCount(int headCount) {
        return Math.max(1, (headCount * ratioPercent + 99) / 100);
    }
}

package com.example.starter.domain;

/**
 * 抽检结果：逐只提交阴性或阳性；任一阳性使整批进入专项隔离。
 */
public enum SampleResult {
    /** 阴性。 */
    NEGATIVE,
    /** 阳性，整批进入专项隔离，受控出厂拒绝。 */
    POSITIVE
}

package com.example.starter.domain;

/**
 * 抽检清单状态：OPEN 抽检中，COMPLETED 全部样本已提交结果。
 */
public enum ChecklistStatus {
    /** 抽检中，尚有样本未提交结果，出厂门禁锁定。 */
    OPEN,
    /** 全部样本已提交结果。 */
    COMPLETED
}

