package com.example.starter.service;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.time.Clock;
import java.time.Instant;
import java.util.Optional;
import java.util.function.Supplier;

import com.example.starter.error.ApiException;
import com.example.starter.repo.BatchRepository;
import com.example.starter.repo.BatchRepository.IdempotencyRow;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.stereotype.Component;

/**
 * 幂等受理组件：指纹覆盖 requestId 与全部业务字段（含版本、集合与精确时刻），
 * 同键同参返回首次冻结结果，同键异参返回 409 且不改变业务状态，失败不占键。
 * 业务变更、版本递增与幂等登记在同一事务内完成。
 */
@Component
public class IdempotencyExecutor {

    private final BatchRepository repo;
    private final Clock clock;
    private final ObjectMapper objectMapper;

    public IdempotencyExecutor(BatchRepository repo, Clock clock, ObjectMapper objectMapper) {
        this.repo = repo;
        this.clock = clock;
        this.objectMapper = objectMapper;
    }

    /**
     * 幂等受理：并发下同键请求依赖 requestId 全局唯一约束，仅首次受理成功，其余重放首次结果。
     *
     * @param endpoint  受理接口标识
     * @param requestId 调用方请求标识，全局唯一
     * @param request   完整业务请求（指纹覆盖其全部字段）
     * @param type      响应类型
     * @param action    业务动作，与幂等登记同事务
     * @param <T>       响应类型参数
     * @return 首次受理的响应；同键同参重放时原样返回
     */
    public <T> T execute(String endpoint, String requestId, Object request, Class<T> type,
                         Supplier<T> action) {
        String fingerprint = fingerprint(requestId, request);
        Optional<IdempotencyRow> existing = repo.findIdempotency(requestId);
        if (existing.isPresent()) {
            IdempotencyRow record = existing.get();
            if (!record.fingerprint().equals(fingerprint)) {
                throw ApiException.conflict("相同 requestId 携带不同业务参数，拒绝受理");
            }
            return readValue(record.responseBody(), type);
        }
        try {
            T result = action.get();
            repo.insertIdempotency(requestId, endpoint, fingerprint, writeValue(result),
                    Instant.now(clock).toString());
            return result;
        } catch (DuplicateKeyException e) {
            Optional<IdempotencyRow> concurrent = repo.findIdempotency(requestId);
            if (concurrent.isPresent() && concurrent.get().fingerprint().equals(fingerprint)) {
                return readValue(concurrent.get().responseBody(), type);
            }
            throw ApiException.conflict("并发受理冲突：批次或请求标识已被其他请求占用");
        }
    }

    /**
     * 请求指纹：requestId 与完整请求 JSON 的 SHA-256。JSON 为结构化无歧义编码，
     * 合法文本含分隔符（如换行、竖线）亦按字段边界区分，不会与拼接串混淆。
     */
    private String fingerprint(String requestId, Object request) {
        try {
            String json = objectMapper.writeValueAsString(request);
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            byte[] hash = digest.digest(
                    (requestId + "\n" + json).getBytes(StandardCharsets.UTF_8));
            StringBuilder hex = new StringBuilder(hash.length * 2);
            for (byte b : hash) {
                hex.append(Character.forDigit((b >> 4) & 0xF, 16));
                hex.append(Character.forDigit(b & 0xF, 16));
            }
            return hex.toString();
        } catch (Exception e) {
            throw new IllegalStateException("请求指纹计算失败", e);
        }
    }

    private <T> T readValue(String json, Class<T> type) {
        try {
            return objectMapper.readValue(json, type);
        } catch (Exception e) {
            throw new IllegalStateException("幂等响应反序列化失败", e);
        }
    }

    private String writeValue(Object value) {
        try {
            return objectMapper.writeValueAsString(value);
        } catch (Exception e) {
            throw new IllegalStateException("幂等响应序列化失败", e);
        }
    }
}

