package com.example.starter.repo;

import java.sql.ResultSet;
import java.sql.SQLException;
import java.util.List;
import java.util.Optional;

import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * 风险抽检数据访问层：抽检清单与样本结果，全部使用参数化 SQL，时间以 UTC ISO-8601 字符串存取。
 */
@Repository
public class RiskRepository {

    private final JdbcTemplate jdbc;

    public RiskRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** 抽检清单行。declaredHeads 为冻结申报头只集合的 JSON 数组。 */
    public record ChecklistRow(long id, long batchId, int listNo, String riskLevel, String ruleVersion,
                               int sampleCount, String declaredHeads, String status,
                               boolean current, int version, String createdAt, String completedAt) {
    }

    /** 抽检样本行。result 为 NULL 表示未提交。 */
    public record SampleRow(long id, long checklistId, String headNo, String result, String resultAt) {
    }

    private static final RowMapper<ChecklistRow> CHECKLIST_MAPPER = (rs, n) -> new ChecklistRow(
            rs.getLong("id"), rs.getLong("batch_id"), rs.getInt("list_no"),
            rs.getString("risk_level"), rs.getString("rule_version"), rs.getInt("sample_count"),
            rs.getString("declared_heads"), rs.getString("status"), rs.getBoolean("current_flag"),
            rs.getInt("version"), rs.getString("created_at"), rs.getString("completed_at"));

    private static final RowMapper<SampleRow> SAMPLE_MAPPER = (rs, n) -> new SampleRow(
            rs.getLong("id"), rs.getLong("checklist_id"), rs.getString("head_no"),
            rs.getString("result"), rs.getString("result_at"));

    // ---------- 抽检清单 ----------

    public void insertChecklist(long batchId, int listNo, String riskLevel, String ruleVersion,
                                int sampleCount, String declaredHeads, boolean current,
                                int version, String createdAt) {
        jdbc.update("INSERT INTO risk_checklist(batch_id, list_no, risk_level, rule_version,"
                        + " sample_count, declared_heads, status, current_flag, version, created_at)"
                        + " VALUES (?,?,?,?,?,?,'OPEN',?,?,?)",
                batchId, listNo, riskLevel, ruleVersion, sampleCount, declaredHeads, current,
                version, createdAt);
    }

    public Optional<ChecklistRow> findChecklist(long batchId, int listNo) {
        List<ChecklistRow> rows = jdbc.query(
                "SELECT * FROM risk_checklist WHERE batch_id = ? AND list_no = ?",
                CHECKLIST_MAPPER, batchId, listNo);
        return rows.stream().findFirst();
    }

    /** 当前清单：同一批次仅一行 current_flag = TRUE。 */
    public Optional<ChecklistRow> findCurrentChecklist(long batchId) {
        List<ChecklistRow> rows = jdbc.query(
                "SELECT * FROM risk_checklist WHERE batch_id = ? AND current_flag = TRUE",
                CHECKLIST_MAPPER, batchId);
        return rows.stream().findFirst();
    }

    public List<ChecklistRow> findChecklists(long batchId) {
        return jdbc.query("SELECT * FROM risk_checklist WHERE batch_id = ? ORDER BY list_no",
                CHECKLIST_MAPPER, batchId);
    }

    public boolean existsAnyChecklist(long batchId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM risk_checklist WHERE batch_id = ?", Integer.class, batchId);
        return count != null && count > 0;
    }

    /** 是否存在未完成的清单（出厂门禁判定用）。 */
    public boolean existsOpenChecklist(long batchId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM risk_checklist WHERE batch_id = ? AND status = 'OPEN'",
                Integer.class, batchId);
        return count != null && count > 0;
    }

    /** 批次内最大清单序号，无清单时返回 0。 */
    public int maxListNo(long batchId) {
        Integer max = jdbc.queryForObject(
                "SELECT COALESCE(MAX(list_no), 0) FROM risk_checklist WHERE batch_id = ?",
                Integer.class, batchId);
        return max == null ? 0 : max;
    }

    /** 取消当前清单标识（另开补充清单前调用）。 */
    public void clearCurrentFlag(long checklistId) {
        jdbc.update("UPDATE risk_checklist SET current_flag = FALSE WHERE id = ?", checklistId);
    }

    /**
     * 风险变更落库：仅版本匹配时更新，返回受影响行数（0 表示版本冲突）。
     * sampleCount 为变更后的冻结抽样数量（降低风险不缩减时与现值相同）。
     */
    public int applyRiskChange(long checklistId, int expectedVersion, String riskLevel,
                               String ruleVersion, int sampleCount) {
        return jdbc.update("UPDATE risk_checklist SET risk_level = ?, rule_version = ?,"
                        + " sample_count = ?, version = version + 1"
                        + " WHERE id = ? AND version = ? AND status = 'OPEN'",
                riskLevel, ruleVersion, sampleCount, checklistId, expectedVersion);
    }

    /**
     * 抽检结果落库后推进清单：版本加 1；全部样本已提交时置 COMPLETED 并记录完成时间。
     * 仅版本匹配时更新，返回受影响行数（0 表示版本冲突）。
     */
    public int advanceAfterResult(long checklistId, int expectedVersion, boolean complete,
                                  String completedAt) {
        if (complete) {
            return jdbc.update("UPDATE risk_checklist SET version = version + 1,"
                            + " status = 'COMPLETED', completed_at = ?"
                            + " WHERE id = ? AND version = ? AND status = 'OPEN'",
                    completedAt, checklistId, expectedVersion);
        }
        return jdbc.update("UPDATE risk_checklist SET version = version + 1"
                        + " WHERE id = ? AND version = ? AND status = 'OPEN'",
                checklistId, expectedVersion);
    }

    // ---------- 抽检样本 ----------

    public void insertSample(long checklistId, String headNo) {
        jdbc.update("INSERT INTO checklist_sample(checklist_id, head_no) VALUES (?,?)",
                checklistId, headNo);
    }

    public List<SampleRow> findSamples(long checklistId) {
        return jdbc.query("SELECT * FROM checklist_sample WHERE checklist_id = ? ORDER BY head_no",
                SAMPLE_MAPPER, checklistId);
    }

    public Optional<SampleRow> findSample(long checklistId, String headNo) {
        List<SampleRow> rows = jdbc.query(
                "SELECT * FROM checklist_sample WHERE checklist_id = ? AND head_no = ?",
                SAMPLE_MAPPER, checklistId, headNo);
        return rows.stream().findFirst();
    }

    /** 登记逐只抽检结果：仅未提交结果的样本可更新，返回受影响行数。 */
    public int setSampleResult(long sampleId, String result, String resultAt) {
        return jdbc.update("UPDATE checklist_sample SET result = ?, result_at = ?"
                        + " WHERE id = ? AND result IS NULL",
                result, resultAt, sampleId);
    }

    /** 未提交结果的样本数：为 0 时清单完成。 */
    public int countPendingSamples(long checklistId) {
        Integer count = jdbc.queryForObject(
                "SELECT COUNT(*) FROM checklist_sample WHERE checklist_id = ? AND result IS NULL",
                Integer.class, checklistId);
        return count == null ? 0 : count;
    }
}

