/**
 * 风险分层抽检接口：绑定风险等级、风险变更、逐只抽检结果与清单/隔离原因查询。
 */
@RestController
@RequestMapping("/api/batches/{batchNo}/risk-checklists")
public class RiskController {

    private final RiskService service;

    public RiskController(RiskService service) {
        this.service = service;
    }

    /** 绑定风险等级并创建首个抽检清单（幂等）：冻结编号清单、规则版本与申报头只集合。 */
    @PostMapping
    public RiskChecklistResponse create(@PathVariable String batchNo,
                                        @Valid @RequestBody RiskChecklistCreateRequest request) {
        return service.createChecklist(batchNo, request);
    }

    /** 风险等级变更（幂等）：未完成提高原子扩充、降低不缩减；已完成另开补充清单并再锁出厂。 */
    @PostMapping("/current/risk")
    public RiskChecklistResponse changeRisk(@PathVariable String batchNo,
                                            @Valid @RequestBody RiskChangeRequest request) {
        return service.changeRisk(batchNo, request);
    }

    /** 逐只抽检结果提交（幂等）：清单外拒绝，重复同结果无新记录，异结果冲突。 */
    @PostMapping("/current/results")
    public RiskChecklistResponse submitResult(@PathVariable String batchNo,
                                              @Valid @RequestBody SampleResultRequest request) {
        return service.submitResult(batchNo, request);
    }

    /** 清单及隔离原因查询：专项隔离状态、原因与全部抽检清单。 */
    @GetMapping
    public RiskOverviewResponse overview(@PathVariable String batchNo) {
        return service.overview(batchNo);
    }
}

