package com.example.starter;

import java.util.List;
import java.util.stream.IntStream;

import com.example.starter.web.dto.BatchView;
import com.example.starter.web.dto.ChecklistView;
import com.example.starter.web.dto.JudgmentRequest;
import com.example.starter.web.dto.JudgmentResponse;
import com.example.starter.web.dto.ReleaseRequest;
import com.example.starter.web.dto.ReleaseResponse;
import com.example.starter.web.dto.RiskChangeRequest;
import com.example.starter.web.dto.RiskChecklistCreateRequest;
import com.example.starter.web.dto.RiskChecklistResponse;
import com.example.starter.web.dto.RiskOverviewResponse;
import com.example.starter.web.dto.SampleResultRequest;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 风险分层抽检清单与出厂门禁测试：抽样规则与字典序、逐只结果、专项隔离、
 * 风险变更扩充/不缩减/补充清单、迟到告警、版本与幂等、参数与对象错误语义。
 */
class RiskChecklistTest extends BaseIntegrationTest {

    // ---------- 主流程与抽样规则 ----------

    @Test
    @DisplayName("主流程：绑定普通风险抽检1只，全部阴性解除门禁后核销放行")
    void mainFlowAllNegativeReleases() throws Exception {
        List<String> heads = List.of("H1", "H2", "H3", "H4", "H5");
        declareOk("d-1", "B-R1", heads);
        preQuarantineOk("B-R1", "pq-1");

        RiskChecklistResponse created = createOk("B-R1", "rc-1", "NORMAL", "RV-2026-01");
        ChecklistView list = created.checklist();
        assertFalse(created.late());
        assertEquals(1, list.listNo());
        assertEquals("NORMAL", list.riskLevel());
        assertEquals("RV-2026-01", list.ruleVersion());
        assertEquals(1, list.sampleCount());
        assertEquals(1, list.version());
        assertEquals("OPEN", list.status());
        assertTrue(list.current());
        assertEquals(heads, list.declaredHeads());
        assertEquals(List.of("H1"), list.samples().stream().map(ChecklistView.SampleView::headNo).toList());
        assertNull(list.samples().get(0).result());

        // 抽检未完成：判定完成后出厂仍被门禁拦截（422）
        for (String headNo : heads) {
            inspectOk("B-R1", "i-" + headNo, headNo);
        }
        judgeAllQualified("B-R1", "j-1", heads);
        postJson("/api/batches/B-R1/release", new ReleaseRequest("rel-0", "核销员甲"))
                .andExpect(status().isUnprocessableEntity());

        // 全部样本阴性：清单完成，门禁解除，核销放行
        RiskChecklistResponse resulted = resultOk("B-R1", "rr-1", "H1", "NEGATIVE", 1);
        assertEquals("COMPLETED", resulted.checklist().status());
        assertEquals(2, resulted.checklist().version());
        assertNotNull(resulted.checklist().completedAt());
        ReleaseResponse released = postOk("/api/batches/B-R1/release",
                new ReleaseRequest("rel-1", "核销员甲"), ReleaseResponse.class);
        assertEquals("RELEASED", released.status());
    }

    @Test
    @DisplayName("抽样数量：头只数乘比例向上取整且至少1，按头只编号字典序选前N只")
    void sampleCountCeilAndLexicographicSelection() throws Exception {
        // 10 头加严 30%：ceil(10*0.3)=3，字典序前 3 只为 H1、H10、H2
        List<String> heads = IntStream.rangeClosed(1, 10).mapToObj(i -> "H" + i).toList();
        declareOk("d-1", "B-SEL", heads);
        preQuarantineOk("B-SEL", "pq-1");
        ChecklistView strict = createOk("B-SEL", "rc-1", "STRICT", "RV-1").checklist();
        assertEquals(3, strict.sampleCount());
        assertEquals(List.of("H1", "H10", "H2"),
                strict.samples().stream().map(ChecklistView.SampleView::headNo).toList());

        // 1 头普通 10%：ceil(0.1)=1，至少 1 只
        declareOk("d-2", "B-MIN", List.of("H1"));
        preQuarantineOk("B-MIN", "pq-2");
        ChecklistView minimal = createOk("B-MIN", "rc-2", "NORMAL", "RV-1").checklist();
        assertEquals(1, minimal.sampleCount());
        assertEquals(1, minimal.samples().size());

        // 5 头加严 30%：ceil(1.5)=2
        declareOk("d-3", "B-CEIL", List.of("H1", "H2", "H3", "H4", "H5"));
        preQuarantineOk("B-CEIL", "pq-3");
        ChecklistView ceiled = createOk("B-CEIL", "rc-3", "STRICT", "RV-1").checklist();
        assertEquals(2, ceiled.sampleCount());
        assertEquals(List.of("H1", "H2"),
                ceiled.samples().stream().map(ChecklistView.SampleView::headNo).toList());
    }

    @Test
    @DisplayName("冻结证据：编号清单、风险规则版本与申报头只集合随清单冻结")
    void frozenEvidenceOnChecklist() throws Exception {
        List<String> heads = List.of("H2", "H1", "H3");
        declareOk("d-1", "B-FRZ", heads);
        preQuarantineOk("B-FRZ", "pq-1");
        ChecklistView list = createOk("B-FRZ", "rc-1", "STRICT", "RV-FROZEN-9").checklist();
        // 申报集合按字典序冻结（与申报顺序无关），ceil(3*0.3)=1 只
        assertEquals(List.of("H1", "H2", "H3"), list.declaredHeads());
        assertEquals("RV-FROZEN-9", list.ruleVersion());
        assertEquals(List.of("H1"),
                list.samples().stream().map(ChecklistView.SampleView::headNo).toList());
    }

    // ---------- 逐只结果 ----------

    @Test
    @DisplayName("清单外结果拒绝422，重复同结果无新记录，异结果冲突422")
    void resultSubmissionRules() throws Exception {
        declareOk("d-1", "B-RES", List.of("H1", "H2", "H3", "H4", "H5"));
        preQuarantineOk("B-RES", "pq-1");
        createOk("B-RES", "rc-1", "NORMAL", "RV-1"); // 样本仅 H1

        // 清单外头只：422
        postJson("/api/batches/B-RES/risk-checklists/current/results",
                new SampleResultRequest("rr-0", "H9", "NEGATIVE", 1))
                .andExpect(status().isUnprocessableEntity());

        // 首次提交阴性：版本 1→2
        RiskChecklistResponse first = resultOk("B-RES", "rr-1", "H1", "NEGATIVE", 1);
        assertEquals(2, first.checklist().version());
        assertEquals("NEGATIVE", first.checklist().samples().get(0).result());

        // 重复同结果（新 requestId）：无新记录，版本不变
        RiskChecklistResponse repeated = resultOk("B-RES", "rr-2", "H1", "NEGATIVE", 2);
        assertEquals(2, repeated.checklist().version());
        assertEquals(1, countRows("checklist_sample"));
        assertEquals("NEGATIVE", repeated.checklist().samples().get(0).result());

        // 异结果冲突：422，结果与版本不变
        postJson("/api/batches/B-RES/risk-checklists/current/results",
                new SampleResultRequest("rr-3", "H1", "POSITIVE", 2))
                .andExpect(status().isUnprocessableEntity());
        ChecklistView after = overview("B-RES").checklists().get(0);
        assertEquals("NEGATIVE", after.samples().get(0).result());
        assertEquals(2, after.version());
    }

    @Test
    @DisplayName("任一阳性整批专项隔离：四类判定保留，受控出厂拒绝，隔离原因可查")
    void positiveIsolatesBatchAndBlocksRelease() throws Exception {
        List<String> heads = List.of("H1", "H2", "H3", "H4", "H5");
        declareOk("d-1", "B-ISO", heads);
        preQuarantineOk("B-ISO", "pq-1");
        createOk("B-ISO", "rc-1", "NORMAL", "RV-1");

        RiskChecklistResponse positive = resultOk("B-ISO", "rr-1", "H1", "POSITIVE", 1);
        assertEquals("POSITIVE", positive.checklist().samples().get(0).result());
        assertEquals("COMPLETED", positive.checklist().status());

        // 既有四类判定保留：同步检验与判定分流照常
        for (String headNo : heads) {
            inspectOk("B-ISO", "i-" + headNo, headNo);
        }
        judgeAllQualified("B-ISO", "j-1", heads);
        assertEquals("JUDGED", getView("B-ISO").status());

        // 受控出厂拒绝（422）
        postJson("/api/batches/B-ISO/release", new ReleaseRequest("rel-1", "核销员甲"))
                .andExpect(status().isUnprocessableEntity());

        // 清单及隔离原因查询
        RiskOverviewResponse overview = overview("B-ISO");
        assertTrue(overview.isolated());
        assertNotNull(overview.isolatedAt());
        assertTrue(overview.isolationReason().contains("H1"));
        assertTrue(overview.isolationReason().contains("阳性"));
        assertEquals(1, overview.checklists().size());
    }

    // ---------- 风险变更 ----------

    @Test
    @DisplayName("提高风险等级原子扩充清单并保留既有结果，降低不缩减")
    void raiseExpandsAtomicallyLowerKeepsList() throws Exception {
        List<String> heads = IntStream.rangeClosed(1, 20).mapToObj(i -> "H%02d".formatted(i)).toList();
        declareOk("d-1", "B-EXP", heads);
        preQuarantineOk("B-EXP", "pq-1");
        // 普通 10%：2 只（H01、H02）
        createOk("B-EXP", "rc-1", "NORMAL", "RV-1");
        resultOk("B-EXP", "rr-1", "H01", "NEGATIVE", 1);

        // 提高为加严 30%：扩充至 6 只，既有 H01 阴性结果保留，版本 2→3
        RiskChecklistResponse raised = changeOk("B-EXP", "rch-1", "STRICT", "RV-2", 2);
        ChecklistView expanded = raised.checklist();
        assertEquals(3, expanded.version());
        assertEquals("STRICT", expanded.riskLevel());
        assertEquals("RV-2", expanded.ruleVersion());
        assertEquals(6, expanded.sampleCount());
        assertEquals("OPEN", expanded.status());
        assertEquals(List.of("H01", "H02", "H03", "H04", "H05", "H06"),
                expanded.samples().stream().map(ChecklistView.SampleView::headNo).toList());
        ChecklistView.SampleView h01 = expanded.samples().get(0);
        assertEquals("NEGATIVE", h01.result());
        assertNotNull(h01.resultAt());
        assertEquals(6, countRows("checklist_sample"));

        // 降低为普通：不缩减，清单与结果保持，版本 3→4
        RiskChecklistResponse lowered = changeOk("B-EXP", "rch-2", "NORMAL", "RV-1", 3);
        ChecklistView shrunk = lowered.checklist();
        assertEquals(4, shrunk.version());
        assertEquals("NORMAL", shrunk.riskLevel());
        assertEquals(6, shrunk.sampleCount());
        assertEquals(6, shrunk.samples().size());
        assertEquals("NEGATIVE", shrunk.samples().get(0).result());
        assertEquals(6, countRows("checklist_sample"));
    }

    @Test
    @DisplayName("风险等级与规则版本均未变化拒绝422")
    void noOpRiskChangeRejected() throws Exception {
        declareOk("d-1", "B-NOOP", List.of("H1"));
        preQuarantineOk("B-NOOP", "pq-1");
        createOk("B-NOOP", "rc-1", "NORMAL", "RV-1");
        postJson("/api/batches/B-NOOP/risk-checklists/current/risk",
                new RiskChangeRequest("rch-1", "NORMAL", "RV-1", 1))
                .andExpect(status().isUnprocessableEntity());
    }

    @Test
    @DisplayName("已完成清单不可改：新增风险另开补充清单并再次锁出厂")
    void completedListChangeOpensSupplementaryAndRelocksGate() throws Exception {
        List<String> heads = List.of("H1", "H2", "H3", "H4", "H5");
        declareOk("d-1", "B-SUP", heads);
        preQuarantineOk("B-SUP", "pq-1");
        createOk("B-SUP", "rc-1", "NORMAL", "RV-1");
        resultOk("B-SUP", "rr-1", "H1", "NEGATIVE", 1); // 清单 1 完成

        // 已完成清单上新增风险：另开补充清单 #2（加严 30% → 2 只），再次锁出厂
        RiskChecklistResponse changed = changeOk("B-SUP", "rch-1", "STRICT", "RV-2", 2);
        ChecklistView supplementary = changed.checklist();
        assertEquals(2, supplementary.listNo());
        assertEquals(1, supplementary.version());
        assertTrue(supplementary.current());
        assertEquals("OPEN", supplementary.status());
        assertEquals(2, supplementary.sampleCount());
        assertEquals(List.of("H1", "H2"),
                supplementary.samples().stream().map(ChecklistView.SampleView::headNo).toList());

        // 原清单冻结不变
        RiskOverviewResponse overview = overview("B-SUP");
        assertEquals(2, overview.checklists().size());
        ChecklistView first = overview.checklists().get(0);
        assertEquals("COMPLETED", first.status());
        assertFalse(first.current());
        assertEquals(2, first.version());
        assertEquals("NEGATIVE", first.samples().get(0).result());

        // 补充清单未完成：出厂门禁拦截
        for (String headNo : heads) {
            inspectOk("B-SUP", "i-" + headNo, headNo);
        }
        judgeAllQualified("B-SUP", "j-1", heads);
        postJson("/api/batches/B-SUP/release", new ReleaseRequest("rel-1", "核销员甲"))
                .andExpect(status().isUnprocessableEntity());

        // 补充清单全部阴性：门禁解除，核销放行
        resultOk("B-SUP", "rr-2", "H1", "NEGATIVE", 1);
        resultOk("B-SUP", "rr-3", "H2", "NEGATIVE", 2);
        ReleaseResponse released = postOk("/api/batches/B-SUP/release",
                new ReleaseRequest("rel-2", "核销员甲"), ReleaseResponse.class);
        assertEquals("RELEASED", released.status());
    }

    // ---------- 核销后迟到 ----------

    @Test
    @DisplayName("核销后风险信息只记迟到告警，不追改冻结出厂证据")
    void postReleaseRiskInfoOnlyLateAlert() throws Exception {
        List<String> heads = List.of("H1", "H2", "H3", "H4", "H5");
        declareOk("d-1", "B-LATE", heads);
        preQuarantineOk("B-LATE", "pq-1");
        createOk("B-LATE", "rc-1", "NORMAL", "RV-1");
        resultOk("B-LATE", "rr-1", "H1", "NEGATIVE", 1);
        for (String headNo : heads) {
            inspectOk("B-LATE", "i-" + headNo, headNo);
        }
        judgeAllQualified("B-LATE", "j-1", heads);
        ReleaseResponse released = postOk("/api/batches/B-LATE/release",
                new ReleaseRequest("rel-1", "核销员甲"), ReleaseResponse.class);
        assertEquals("RELEASED", released.status());

        // 核销后风险变更：迟到告警，清单版本与内容不变
        RiskChecklistResponse lateChange = changeOk("B-LATE", "rch-1", "STRICT", "RV-2", 2);
        assertTrue(lateChange.late());
        assertEquals(2, lateChange.checklist().version());
        assertEquals("NORMAL", lateChange.checklist().riskLevel());

        // 核销后抽检结果：迟到告警，结果不追改
        RiskChecklistResponse lateResult = resultOk("B-LATE", "rr-2", "H1", "POSITIVE", 2);
        assertTrue(lateResult.late());
        assertEquals("NEGATIVE", lateResult.checklist().samples().get(0).result());

        // 核销后绑定新清单：迟到告警，不新增清单
        RiskChecklistResponse lateCreate = postOk("/api/batches/B-LATE/risk-checklists",
                new RiskChecklistCreateRequest("rc-2", "STRICT", "RV-9"),
                RiskChecklistResponse.class);
        assertTrue(lateCreate.late());

        // 冻结出厂证据不变：批次状态、核销时间、清单与隔离标识均未追改
        BatchView view = getView("B-LATE");
        assertEquals("RELEASED", view.status());
        assertEquals(released.releasedAt(), view.releasedAt());
        assertEquals(3, view.lateEvents().size());
        assertEquals(List.of("LATE_RISK_CHANGE", "LATE_RISK_RESULT", "LATE_RISK_CHECKLIST"),
                view.lateEvents().stream().map(BatchView.LateEventView::eventType).toList());
        RiskOverviewResponse overview = overview("B-LATE");
        assertFalse(overview.isolated());
        assertEquals(1, overview.checklists().size());
        assertEquals(2, overview.checklists().get(0).version());
        assertEquals("NEGATIVE", overview.checklists().get(0).samples().get(0).result());
    }

    // ---------- 版本与幂等 ----------

    @Test
    @DisplayName("expectedVersion 与清单版本不一致拒绝422，成功变更版本加1")
    void versionConflictRejected() throws Exception {
        declareOk("d-1", "B-VER", List.of("H1", "H2", "H3", "H4", "H5"));
        preQuarantineOk("B-VER", "pq-1");
        createOk("B-VER", "rc-1", "NORMAL", "RV-1"); // 版本 1

        postJson("/api/batches/B-VER/risk-checklists/current/results",
                new SampleResultRequest("rr-1", "H1", "NEGATIVE", 5))
                .andExpect(status().isUnprocessableEntity());
        postJson("/api/batches/B-VER/risk-checklists/current/risk",
                new RiskChangeRequest("rch-1", "STRICT", "RV-2", 2))
                .andExpect(status().isUnprocessableEntity());

        // 正确版本：变更成功，版本 1→2；再次用旧版本拒绝
        RiskChecklistResponse changed = changeOk("B-VER", "rch-2", "STRICT", "RV-2", 1);
        assertEquals(2, changed.checklist().version());
        postJson("/api/batches/B-VER/risk-checklists/current/risk",
                new RiskChangeRequest("rch-3", "NORMAL", "RV-1", 1))
                .andExpect(status().isUnprocessableEntity());
    }

    @Test
    @DisplayName("写操作幂等：同键同参重放首次冻结结果，同键异参409，失败不占键")
    void idempotencyReplayConflictAndFailure() throws Exception {
        declareOk("d-1", "B-IDM", List.of("H1", "H2", "H3", "H4", "H5"));
        preQuarantineOk("B-IDM", "pq-1");

        // 同键同参重放：响应逐字节一致，只创建一次
        RiskChecklistCreateRequest create = new RiskChecklistCreateRequest("rc-1", "NORMAL", "RV-1");
        String first = postJson("/api/batches/B-IDM/risk-checklists", create)
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        String replayed = postJson("/api/batches/B-IDM/risk-checklists", create)
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        assertEquals(first, replayed);
        assertEquals(1, countRows("risk_checklist"));

        // 同键异参：409，状态不变
        postJson("/api/batches/B-IDM/risk-checklists",
                new RiskChecklistCreateRequest("rc-1", "STRICT", "RV-1"))
                .andExpect(status().isConflict());
        assertEquals(1, countRows("risk_checklist"));

        // 失败不占键：版本冲突 422 后，同一 requestId 携带正确参数可成功受理
        postJson("/api/batches/B-IDM/risk-checklists/current/results",
                new SampleResultRequest("rr-1", "H1", "NEGATIVE", 9))
                .andExpect(status().isUnprocessableEntity());
        RiskChecklistResponse recovered = resultOk("B-IDM", "rr-1", "H1", "NEGATIVE", 1);
        assertEquals(2, recovered.checklist().version());
    }

    @Test
    @DisplayName("指纹结构化无歧义：含分隔符合法文本按字段边界区分")
    void fingerprintStructuredWithSeparators() throws Exception {
        declareOk("d-1", "B-FP", List.of("H1"));
        preQuarantineOk("B-FP", "pq-1");

        // 规则版本含分隔符：同键同参重放一致
        RiskChecklistCreateRequest create =
                new RiskChecklistCreateRequest("rc-1", "NORMAL", "RV|2026\n01");
        String first = postJson("/api/batches/B-FP/risk-checklists", create)
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        String replayed = postJson("/api/batches/B-FP/risk-checklists", create)
                .andExpect(status().isOk()).andReturn().getResponse().getContentAsString();
        assertEquals(first, replayed);

        // 同键异参（截断的相似文本）：409 而非误判为同参
        postJson("/api/batches/B-FP/risk-checklists",
                new RiskChecklistCreateRequest("rc-1", "NORMAL", "RV|2026"))
                .andExpect(status().isConflict());
    }

    // ---------- 参数与对象错误语义 ----------

    @Test
    @DisplayName("参数非法400：缺requestId、未知风险等级、未知抽检结果、缺expectedVersion")
    void invalidParamsBadRequest() throws Exception {
        declareOk("d-1", "B-400", List.of("H1"));
        preQuarantineOk("B-400", "pq-1");

        postJson("/api/batches/B-400/risk-checklists",
                new RiskChecklistCreateRequest(null, "NORMAL", "RV-1"))
                .andExpect(status().isBadRequest());
        postJson("/api/batches/B-400/risk-checklists",
                new RiskChecklistCreateRequest("rc-1", "HIGH", "RV-1"))
                .andExpect(status().isBadRequest());

        createOk("B-400", "rc-2", "NORMAL", "RV-1");
        postJson("/api/batches/B-400/risk-checklists/current/results",
                new SampleResultRequest("rr-1", "H1", "OK", 1))
                .andExpect(status().isBadRequest());
        postJson("/api/batches/B-400/risk-checklists/current/results",
                new SampleResultRequest("rr-2", "H1", "NEGATIVE", null))
                .andExpect(status().isBadRequest());
        postJson("/api/batches/B-400/risk-checklists/current/risk",
                new RiskChangeRequest("rch-1", "STRICT", "RV-2", null))
                .andExpect(status().isBadRequest());
    }

    @Test
    @DisplayName("对象不存在404：批次不存在、批次未绑定抽检清单")
    void notFoundSemantics() throws Exception {
        postJson("/api/batches/B-404/risk-checklists",
                new RiskChecklistCreateRequest("rc-1", "NORMAL", "RV-1"))
                .andExpect(status().isNotFound());
        mockMvc.perform(get("/api/batches/B-404/risk-checklists"))
                .andExpect(status().isNotFound());

        declareOk("d-1", "B-NOLIST", List.of("H1"));
        preQuarantineOk("B-NOLIST", "pq-1");
        postJson("/api/batches/B-NOLIST/risk-checklists/current/risk",
                new RiskChangeRequest("rch-1", "STRICT", "RV-2", 1))
                .andExpect(status().isNotFound());
        postJson("/api/batches/B-NOLIST/risk-checklists/current/results",
                new SampleResultRequest("rr-1", "H1", "NEGATIVE", 1))
                .andExpect(status().isNotFound());

        // 未绑定批次的总览：200 空清单、未隔离
        RiskOverviewResponse overview = overview("B-NOLIST");
        assertFalse(overview.isolated());
        assertTrue(overview.checklists().isEmpty());
    }

    @Test
    @DisplayName("业务拒绝422：宰前检疫合格前绑定、重复绑定当前清单")
    void businessRejections() throws Exception {
        declareOk("d-1", "B-422", List.of("H1"));
        // 未检疫（DECLARED）：422
        postJson("/api/batches/B-422/risk-checklists",
                new RiskChecklistCreateRequest("rc-1", "NORMAL", "RV-1"))
                .andExpect(status().isUnprocessableEntity());

        preQuarantineOk("B-422", "pq-1");
        createOk("B-422", "rc-2", "NORMAL", "RV-1");
        // 已存在当前清单：422
        postJson("/api/batches/B-422/risk-checklists",
                new RiskChecklistCreateRequest("rc-3", "STRICT", "RV-2"))
                .andExpect(status().isUnprocessableEntity());
        assertEquals(1, countRows("risk_checklist"));
    }

    // ---------- 辅助 ----------

    private RiskChecklistResponse createOk(String batchNo, String requestId, String level,
                                           String ruleVersion) throws Exception {
        return postOk("/api/batches/" + batchNo + "/risk-checklists",
                new RiskChecklistCreateRequest(requestId, level, ruleVersion),
                RiskChecklistResponse.class);
    }

    private RiskChecklistResponse changeOk(String batchNo, String requestId, String level,
                                           String ruleVersion, int expectedVersion) throws Exception {
        return postOk("/api/batches/" + batchNo + "/risk-checklists/current/risk",
                new RiskChangeRequest(requestId, level, ruleVersion, expectedVersion),
                RiskChecklistResponse.class);
    }

    private RiskChecklistResponse resultOk(String batchNo, String requestId, String headNo,
                                           String result, int expectedVersion) throws Exception {
        return postOk("/api/batches/" + batchNo + "/risk-checklists/current/results",
                new SampleResultRequest(requestId, headNo, result, expectedVersion),
                RiskChecklistResponse.class);
    }

    private RiskOverviewResponse overview(String batchNo) throws Exception {
        String json = mockMvc.perform(get("/api/batches/{batchNo}/risk-checklists", batchNo))
                .andExpect(status().isOk())
                .andReturn()
                .getResponse()
                .getContentAsString();
        return om.readValue(json, RiskOverviewResponse.class);
    }

    private void judgeAllQualified(String batchNo, String requestId, List<String> headNos)
            throws Exception {
        List<JudgmentRequest.JudgmentItem> items = headNos.stream()
                .map(h -> new JudgmentRequest.JudgmentItem(h, "QUALIFIED", null, null))
                .toList();
        postOk("/api/batches/" + batchNo + "/judgments",
                new JudgmentRequest(requestId, items), JudgmentResponse.class);
    }
}

