package com.example.starter;

import java.util.List;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;
import java.util.function.Supplier;

import com.example.starter.error.ApiException;
import com.example.starter.service.BatchService;
import com.example.starter.service.RiskService;
import com.example.starter.web.dto.ChecklistView;
import com.example.starter.web.dto.JudgmentRequest;
import com.example.starter.web.dto.JudgmentResponse;
import com.example.starter.web.dto.ReleaseRequest;
import com.example.starter.web.dto.RiskChangeRequest;
import com.example.starter.web.dto.RiskChecklistCreateRequest;
import com.example.starter.web.dto.RiskChecklistResponse;
import com.example.starter.web.dto.RiskOverviewResponse;
import com.example.starter.web.dto.SampleResultRequest;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * 风险抽检并发边界测试：阳性与出厂核销竞争、风险变更与最后结果竞争、
 * 并发绑定唯一当前清单、并发同结果提交。真实并发线程 + H2 行锁/唯一约束验证，
 * 断言最终结果与落库数据，不留已放行但漏检的批次。
 */
class RiskConcurrencyTest extends BaseIntegrationTest {

    @Autowired
    private RiskService riskService;

    @Autowired
    private BatchService batchService;

    @Test
    @DisplayName("阳性与出厂核销竞争：不留已放行但漏检的批次")
    void positiveResultRacesWithRelease() throws Exception {
        declareOk("d-1", "B-CPOS", List.of("H1"));
        preQuarantineOk("B-CPOS", "pq-1");
        riskService.createChecklist("B-CPOS", new RiskChecklistCreateRequest("rc-1", "NORMAL", "RV-1"));
        inspectOk("B-CPOS", "i-1", "H1");
        postOk("/api/batches/B-CPOS/judgments",
                new JudgmentRequest("j-1",
                        List.of(new JudgmentRequest.JudgmentItem("H1", "QUALIFIED", null, null))),
                JudgmentResponse.class);

        List<Outcome<Object>> outcomes = runConcurrently(
                () -> riskService.submitResult("B-CPOS",
                        new SampleResultRequest("rr-1", "H1", "POSITIVE", 1)),
                () -> batchService.release("B-CPOS", new ReleaseRequest("rel-1", "核销员甲")));

        // 无论谁先提交：阳性结果登记成功，核销被门禁拦截（422），批次未放行且已隔离
        Outcome<Object> resultOutcome = outcomes.get(0);
        Outcome<Object> releaseOutcome = outcomes.get(1);
        assertNotNull(resultOutcome.value(), "阳性结果须登记成功");
        assertNotNull(releaseOutcome.error(), "出厂核销须被抽检门禁拦截");
        assertEquals(422, releaseOutcome.error().status());
        assertEquals("JUDGED", getView("B-CPOS").status());
        RiskOverviewResponse overview = riskService.overview("B-CPOS");
        assertTrue(overview.isolated());
        assertEquals("POSITIVE", overview.checklists().get(0).samples().get(0).result());
    }

    @Test
    @DisplayName("风险变更与最后结果竞争：同版本仅一方成功，清单状态一致")
    void riskChangeRacesWithLastResult() throws Exception {
        List<String> heads = java.util.stream.IntStream.rangeClosed(1, 10)
                .mapToObj(i -> "H" + i).toList();
        declareOk("d-1", "B-CRACE", heads);
        preQuarantineOk("B-CRACE", "pq-1");
        riskService.createChecklist("B-CRACE", new RiskChecklistCreateRequest("rc-1", "NORMAL", "RV-1"));

        // 同一期望版本并发：提高风险扩充清单 vs 提交最后一只结果
        List<Outcome<RiskChecklistResponse>> outcomes = runConcurrently(
                () -> riskService.changeRisk("B-CRACE",
                        new RiskChangeRequest("rch-1", "STRICT", "RV-2", 1)),
                () -> riskService.submitResult("B-CRACE",
                        new SampleResultRequest("rr-1", "H1", "NEGATIVE", 1)));

        long successes = outcomes.stream().filter(o -> o.error() == null).count();
        long versionConflicts = outcomes.stream()
                .filter(o -> o.error() != null && o.error().status() == 422).count();
        assertEquals(1, successes, "同一期望版本仅一方变更成功");
        assertEquals(1, versionConflicts, "另一方须版本冲突 422");

        // 清单版本只前进一次，状态自洽：已完成则全部样本有结果，未完成则已扩充
        RiskOverviewResponse overview = riskService.overview("B-CRACE");
        assertEquals(1, overview.checklists().size());
        ChecklistView current = overview.checklists().get(0);
        assertEquals(2, current.version());
        if ("COMPLETED".equals(current.status())) {
            assertTrue(current.samples().stream().allMatch(s -> s.result() != null));
        } else {
            assertEquals(3, current.sampleCount());
        }

        // 收尾：补全当前清单全部阴性后，判定并核销放行——验证无漏检即放行的窗口
        ChecklistView latest = current;
        for (ChecklistView.SampleView sample : latest.samples()) {
            if (sample.result() == null) {
                latest = riskService.submitResult("B-CRACE",
                        new SampleResultRequest("rr-fix-" + sample.headNo(), sample.headNo(),
                                "NEGATIVE", latest.version())).checklist();
            }
        }
        assertEquals("COMPLETED", latest.status());
        for (String headNo : heads) {
            inspectOk("B-CRACE", "i-" + headNo, headNo);
        }
        postOk("/api/batches/B-CRACE/judgments",
                new JudgmentRequest("j-1", heads.stream()
                        .map(h -> new JudgmentRequest.JudgmentItem(h, "QUALIFIED", null, null))
                        .toList()),
                JudgmentResponse.class);
        postOk("/api/batches/B-CRACE/release", new ReleaseRequest("rel-1", "核销员甲"),
                com.example.starter.web.dto.ReleaseResponse.class);
        assertEquals("RELEASED", getView("B-CRACE").status());
    }

    @Test
    @DisplayName("并发绑定同一批次：唯一当前清单，其余业务拒绝")
    void concurrentCreateSingleCurrentChecklist() throws Exception {
        declareOk("d-1", "B-CDUP", List.of("H1", "H2", "H3"));
        preQuarantineOk("B-CDUP", "pq-1");

        List<Outcome<RiskChecklistResponse>> outcomes = runConcurrently(
                () -> riskService.createChecklist("B-CDUP",
                        new RiskChecklistCreateRequest("rc-a", "NORMAL", "RV-1")),
                () -> riskService.createChecklist("B-CDUP",
                        new RiskChecklistCreateRequest("rc-b", "STRICT", "RV-1")));

        long successes = outcomes.stream().filter(o -> o.error() == null).count();
        long rejections = outcomes.stream()
                .filter(o -> o.error() != null && o.error().status() == 422).count();
        assertEquals(1, successes, "并发绑定须唯一受理");
        assertEquals(1, rejections, "未受理方须业务拒绝 422");
        assertEquals(1, countRows("risk_checklist"));
        RiskOverviewResponse overview = riskService.overview("B-CDUP");
        assertEquals(1, overview.checklists().stream().filter(ChecklistView::current).count());
    }

    @Test
    @DisplayName("并发同结果提交：仅一次登记，重试同结果无新记录")
    void concurrentSameResultRecordedOnce() throws Exception {
        declareOk("d-1", "B-CSAME", List.of("H1", "H2", "H3", "H4", "H5"));
        preQuarantineOk("B-CSAME", "pq-1");
        riskService.createChecklist("B-CSAME", new RiskChecklistCreateRequest("rc-1", "NORMAL", "RV-1"));

        List<Outcome<RiskChecklistResponse>> outcomes = runConcurrently(
                () -> riskService.submitResult("B-CSAME",
                        new SampleResultRequest("rr-a", "H1", "NEGATIVE", 1)),
                () -> riskService.submitResult("B-CSAME",
                        new SampleResultRequest("rr-b", "H1", "NEGATIVE", 1)));

        long successes = outcomes.stream().filter(o -> o.error() == null).count();
        long versionConflicts = outcomes.stream()
                .filter(o -> o.error() != null && o.error().status() == 422).count();
        assertEquals(1, successes);
        assertEquals(1, versionConflicts, "同版本并发仅一方登记，另一方版本冲突");

        // 冲突方按当前版本重试同结果：无新记录，版本不变
        RiskChecklistResponse retried = riskService.submitResult("B-CSAME",
                new SampleResultRequest("rr-b2", "H1", "NEGATIVE", 2));
        assertEquals(2, retried.checklist().version());
        assertEquals(1, countRows("checklist_sample"));
        assertEquals("NEGATIVE",
                riskService.overview("B-CSAME").checklists().get(0).samples().get(0).result());
    }

    // ---------- 并发辅助 ----------

    /** 并发执行结果：成功值或业务异常。 */
    private record Outcome<T>(T value, ApiException error) {
    }

    /**
     * 真实并发执行两个操作：统一栅栏同时起跑，15 秒超时，返回双方结果。
     */
    private <T> List<Outcome<T>> runConcurrently(Supplier<T> first, Supplier<T> second)
            throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(2);
        CountDownLatch ready = new CountDownLatch(2);
        CountDownLatch start = new CountDownLatch(1);
        try {
            Callable<Outcome<T>> taskFirst = () -> awaitAndRun(ready, start, first);
            Callable<Outcome<T>> taskSecond = () -> awaitAndRun(ready, start, second);
            Future<Outcome<T>> futureFirst = pool.submit(taskFirst);
            Future<Outcome<T>> futureSecond = pool.submit(taskSecond);
            assertTrue(ready.await(10, TimeUnit.SECONDS), "并发线程未就绪");
            start.countDown();
            Outcome<T> outcomeFirst = futureFirst.get(15, TimeUnit.SECONDS);
            Outcome<T> outcomeSecond = futureSecond.get(15, TimeUnit.SECONDS);
            assertNotNull(outcomeFirst);
            assertNotNull(outcomeSecond);
            return List.of(outcomeFirst, outcomeSecond);
        } finally {
            pool.shutdownNow();
            assertTrue(pool.awaitTermination(10, TimeUnit.SECONDS), "并发线程未在超时内结束");
        }
    }

    private static <T> Outcome<T> awaitAndRun(CountDownLatch ready, CountDownLatch start,
                                              Supplier<T> action) throws Exception {
        ready.countDown();
        start.await(10, TimeUnit.SECONDS);
        try {
            return new Outcome<>(action.get(), null);
        } catch (ApiException e) {
            return new Outcome<>(null, e);
        }
    }
}

