28	import org.slf4j.Logger;
29	import org.slf4j.LoggerFactory;
30	import org.springframework.stereotype.Service;
31	import org.springframework.transaction.annotation.Transactional;
32	
33	/**
34	 * 风险分层抽检与出厂门禁服务：宰前检疫合格后绑定合成风险等级，冻结编号清单、
35	 * 风险规则版本与申报头只集合；逐只提交阴性/阳性结果，任一阳性整批专项隔离；
36	 * 全部样本阴性才解除抽检门禁。所有写操作以批次行锁串行化，并以 requestId 幂等。
37	 */
38	@Service
39	public class RiskService {
40	
41	    private static final Logger log = LoggerFactory.getLogger(RiskService.class);
42	
43	    private final BatchRepository repo;
44	    private final RiskRepository riskRepo;
45	    private final Clock clock;
46	    private final IdempotencyExecutor idempotency;
47	    private final ObjectMapper objectMapper;
48	
49	    public RiskService(BatchRepository repo, RiskRepository riskRepo, Clock clock,
50	                       IdempotencyExecutor idempotency, ObjectMapper objectMapper) {
51	        this.repo = repo;
52	        this.riskRepo = riskRepo;
53	        this.clock = clock;
54	        this.idempotency = idempotency;
55	        this.objectMapper = objectMapper;
56	    }
57	
58	    // ---------- 绑定风险等级（创建首个清单） ----------
59	
60	    /**
61	     * 绑定风险等级：冻结按头只编号字典序选取的前 N 只编号清单、风险规则版本与申报头只集合，
62	     * 清单版本从 1 开始。同一批次只一个当前清单；核销后绑定仅记迟到告警。
63	     */
64	    @Transactional
65	    public RiskChecklistResponse createChecklist(String batchNo, RiskChecklistCreateRequest req) {
66	        return idempotency.execute("risk-checklist-create", req.requestId(), req,
67	                RiskChecklistResponse.class, () -> doCreate(batchNo, req));
68	    }
69	
70	    private RiskChecklistResponse doCreate(String batchNo, RiskChecklistCreateRequest req) {
71	        BatchRow batch = mustLock(batchNo);
72	        RiskLevel level = parseLevel(req.riskLevel());
73	        String now = now();
74	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
75	            repo.insertLateEvent(batch.id(), "LATE_RISK_CHECKLIST",
76	                    "核销后迟到风险绑定：等级 " + level.name() + "，规则版本 " + req.ruleVersion(), now);
77	            log.warn("批次 {} 已出厂核销，风险绑定迟到登记并告警", batchNo);
78	            return new RiskChecklistResponse(batchNo, true, null);
79	        }
80	        if (BatchStatus.DECLARED.name().equals(batch.status())) {
81	            throw ApiException.unprocessable("宰前检疫合格后才能绑定风险抽检清单");
82	        }
83	        if (riskRepo.findCurrentChecklist(batch.id()).isPresent()) {
84	            throw ApiException.unprocessable("批次已存在当前抽检清单，同一批次只一个当前清单");
85	        }
86	        List<String> declaredHeads = declaredHeads(batch.id());
87	        int listNo = riskRepo.maxListNo(batch.id()) + 1;
88	        int sampleCount = level.sampleCount(declaredHeads.size());
89	        riskRepo.insertChecklist(batch.id(), listNo, level.name(), req.ruleVersion(),
90	                sampleCount, writeHeads(declaredHeads), true, 1, now);
91	        ChecklistRow created = riskRepo.findChecklist(batch.id(), listNo).orElseThrow();
92	        for (String headNo : declaredHeads.subList(0, sampleCount)) {
93	            riskRepo.insertSample(created.id(), headNo);
94	        }
95	        return new RiskChecklistResponse(batchNo, false, view(created.id()));
96	    }
97	
98	    // ---------- 风险等级变更 ----------
99	
100	    /**
101	     * 风险变更：抽检未完成前提高风险等级原子扩充清单并保留既有结果，降低不缩减；
102	     * 已完成清单不可改，另开补充清单并再次锁出厂；核销后仅记迟到告警。
103	     */
104	    @Transactional
105	    public RiskChecklistResponse changeRisk(String batchNo, RiskChangeRequest req) {
106	        return idempotency.execute("risk-change", req.requestId(), req,
107	                RiskChecklistResponse.class, () -> doChangeRisk(batchNo, req));
108	    }
109	
110	    private RiskChecklistResponse doChangeRisk(String batchNo, RiskChangeRequest req) {
111	        BatchRow batch = mustLock(batchNo);
112	        RiskLevel level = parseLevel(req.riskLevel());
113	        ChecklistRow current = mustCurrent(batch.id());
114	        String now = now();
115	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
116	            repo.insertLateEvent(batch.id(), "LATE_RISK_CHANGE",
117	                    "核销后迟到风险变更：等级 " + level.name() + "，规则版本 " + req.ruleVersion()
118	                            + "，期望版本 " + req.expectedVersion(), now);
119	            log.warn("批次 {} 已出厂核销，风险变更迟到登记并告警", batchNo);
120	            return new RiskChecklistResponse(batchNo, true, view(current.id()));
121	        }
122	        requireVersion(current, req.expectedVersion());
123	        RiskLevel currentLevel = RiskLevel.valueOf(current.riskLevel());
124	        if (level == currentLevel && current.ruleVersion().equals(req.ruleVersion())) {
125	            throw ApiException.unprocessable("风险等级与规则版本均未变化");
126	        }
127	        if (ChecklistStatus.COMPLETED.name().equals(current.status())) {
128	            // 已完成清单不可改：另开补充清单，再次锁出厂
129	            riskRepo.clearCurrentFlag(current.id());
130	            List<String> declaredHeads = declaredHeads(batch.id());
131	            int listNo = riskRepo.maxListNo(batch.id()) + 1;
132	            int sampleCount = level.sampleCount(declaredHeads.size());
133	            riskRepo.insertChecklist(batch.id(), listNo, level.name(), req.ruleVersion(),
134	                    sampleCount, writeHeads(declaredHeads), true, 1, now);
135	            ChecklistRow supplementary = riskRepo.findChecklist(batch.id(), listNo).orElseThrow();
136	            for (String headNo : declaredHeads.subList(0, sampleCount)) {
137	                riskRepo.insertSample(supplementary.id(), headNo);
138	            }
139	            return new RiskChecklistResponse(batchNo, false, view(supplementary.id()));
140	        }
141	        // 未完成清单：提高原子扩充并保留既有结果，降低不缩减
142	        List<SampleRow> existing = riskRepo.findSamples(current.id());
143	        List<String> declaredHeads = declaredHeads(batch.id());
144	        int required = level.sampleCount(declaredHeads.size());
145	        int newCount = Math.max(existing.size(), required);
146	        if (level.ratioPercent() > currentLevel.ratioPercent() && required > existing.size()) {
147	            Set<String> present = new LinkedHashSet<>();
148	            for (SampleRow row : existing) {
149	                present.add(row.headNo());
150	            }
151	            for (String headNo : declaredHeads.subList(0, required)) {
152	                if (present.add(headNo)) {
153	                    riskRepo.insertSample(current.id(), headNo);
154	                }
155	            }
156	        }
157	        int updated = riskRepo.applyRiskChange(current.id(), req.expectedVersion(), level.name(),
158	                req.ruleVersion(), newCount);
159	        if (updated == 0) {
160	            throw ApiException.unprocessable("清单版本冲突：期望 " + req.expectedVersion()
161	                    + "，当前 " + current.version());
162	        }
163	        return new RiskChecklistResponse(batchNo, false, view(current.id()));
164	    }
165	
166	    // ---------- 逐只抽检结果 ----------
167	
168	    /**
169	     * 提交抽检结果：清单外结果拒绝；重复同结果无新记录、不递增版本；异结果冲突；
170	     * 任一阳性整批专项隔离；全部样本提交后清单完成。核销后仅记迟到告警。
171	     */
172	    @Transactional
173	    public RiskChecklistResponse submitResult(String batchNo, SampleResultRequest req) {
174	        return idempotency.execute("risk-result", req.requestId(), req,
175	                RiskChecklistResponse.class, () -> doSubmitResult(batchNo, req));
176	    }
177	
178	    private RiskChecklistResponse doSubmitResult(String batchNo, SampleResultRequest req) {
179	        BatchRow batch = mustLock(batchNo);
180	        SampleResult result = parseResult(req.result());
181	        ChecklistRow current = mustCurrent(batch.id());
182	        String now = now();
183	        if (BatchStatus.RELEASED.name().equals(batch.status())) {
184	            repo.insertLateEvent(batch.id(), "LATE_RISK_RESULT",
185	                    "核销后迟到抽检结果：头只 " + req.headNo() + "，结果 " + result.name(), now);
186	            log.warn("批次 {} 已出厂核销，抽检结果迟到登记并告警", batchNo);
187	            return new RiskChecklistResponse(batchNo, true, view(current.id()));
188	        }
189	        requireVersion(current, req.expectedVersion());
190	        SampleRow sample = riskRepo.findSample(current.id(), req.headNo())
191	                .orElseThrow(() -> ApiException.unprocessable(
192	                        "清单外头只，拒绝登记抽检结果：" + req.headNo()));
193	        if (sample.result() != null) {
194	            if (sample.result().equals(result.name())) {
195	                // 重复同结果：无新记录，版本不变
196	                return new RiskChecklistResponse(batchNo, false, view(current.id()));
197	            }
198	            throw ApiException.unprocessable("抽检结果冲突：头只 " + req.headNo()
199	                    + " 已登记 " + sample.result() + "，拒绝改为 " + result.name());
200	        }
201	        riskRepo.setSampleResult(sample.id(), result.name(), now);
202	        boolean complete = riskRepo.countPendingSamples(current.id()) == 0;
203	        int updated = riskRepo.advanceAfterResult(current.id(), req.expectedVersion(),
204	                complete, now);
205	        if (updated == 0) {
206	            throw ApiException.unprocessable("清单版本冲突：期望 " + req.expectedVersion()
207	                    + "，当前 " + current.version());
208	        }
209	        if (result == SampleResult.POSITIVE) {
210	            String reason = "清单 #" + current.listNo() + " 头只 " + req.headNo() + " 抽检阳性";
211	            repo.markIsolated(batch.id(), reason, now);
212	            log.warn("批次 {} 进入专项隔离：{}", batchNo, reason);
213	        }
214	        return new RiskChecklistResponse(batchNo, false, view(current.id()));
215	    }
216	
217	    // ---------- 清单及隔离原因查询 ----------
218	
219	    /**
220	     * 批次风险总览：专项隔离状态与原因、全部抽检清单（含冻结编号与逐只结果）。
221	     */
222	    @Transactional(readOnly = true)
223	    public RiskOverviewResponse overview(String batchNo) {
224	        BatchRow batch = repo.findBatchByNo(batchNo)
225	                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
226	        List<ChecklistView> checklists = new ArrayList<>();
227	        for (ChecklistRow row : riskRepo.findChecklists(batch.id())) {
228	            checklists.add(view(row.id()));
229	        }
230	        return new RiskOverviewResponse(batch.batchNo(), batch.isolated(), batch.isolatedAt(),
231	                batch.isolationReason(), checklists);
232	    }
233	
234	    // ---------- 内部：视图 / 校验 / 工具 ----------
235	
236	    /** 行锁读取批次：串行化抽检结果、风险变更与出厂核销。 */
237	    private BatchRow mustLock(String batchNo) {
238	        return repo.findBatchByNoForUpdate(batchNo)
239	                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
240	    }
241	
242	    private ChecklistRow mustCurrent(long batchId) {
243	        return riskRepo.findCurrentChecklist(batchId)
244	                .orElseThrow(() -> ApiException.notFound("批次未绑定风险抽检清单"));
245	    }
246	
247	    private void requireVersion(ChecklistRow current, int expectedVersion) {
