package com.example.starter.service;

import java.time.Clock;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;

import com.example.starter.domain.BatchStatus;
import com.example.starter.domain.ChecklistStatus;
import com.example.starter.domain.RiskLevel;
import com.example.starter.domain.SampleResult;
import com.example.starter.error.ApiException;
import com.example.starter.repo.BatchRepository;
import com.example.starter.repo.BatchRepository.BatchRow;
import com.example.starter.repo.BatchRepository.HeadRow;
import com.example.starter.repo.RiskRepository;
import com.example.starter.repo.RiskRepository.ChecklistRow;
import com.example.starter.repo.RiskRepository.SampleRow;
import com.example.starter.web.dto.ChecklistView;
import com.example.starter.web.dto.RiskChangeRequest;
import com.example.starter.web.dto.RiskChecklistCreateRequest;
import com.example.starter.web.dto.RiskChecklistResponse;
import com.example.starter.web.dto.RiskOverviewResponse;
import com.example.starter.web.dto.SampleResultRequest;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * 风险分层抽检与出厂门禁服务：宰前检疫合格后绑定合成风险等级，冻结编号清单、
 * 风险规则版本与申报头只集合；逐只提交阴性/阳性结果，任一阳性整批专项隔离；
 * 全部样本阴性才解除抽检门禁。所有写操作以批次行锁串行化，并以 requestId 幂等。
 */
@Service
public class RiskService {

    private static final Logger log = LoggerFactory.getLogger(RiskService.class);

    private final BatchRepository repo;
    private final RiskRepository riskRepo;
    private final Clock clock;
    private final IdempotencyExecutor idempotency;
    private final ObjectMapper objectMapper;

    public RiskService(BatchRepository repo, RiskRepository riskRepo, Clock clock,
                       IdempotencyExecutor idempotency, ObjectMapper objectMapper) {
        this.repo = repo;
        this.riskRepo = riskRepo;
        this.clock = clock;
        this.idempotency = idempotency;
        this.objectMapper = objectMapper;
    }

    // ---------- 绑定风险等级（创建首个清单） ----------

    /**
     * 绑定风险等级：冻结按头只编号字典序选取的前 N 只编号清单、风险规则版本与申报头只集合，
     * 清单版本从 1 开始。同一批次只一个当前清单；核销后绑定仅记迟到告警。
     */
    @Transactional
    public RiskChecklistResponse createChecklist(String batchNo, RiskChecklistCreateRequest req) {
        return idempotency.execute("risk-checklist-create", req.requestId(), req,
                RiskChecklistResponse.class, () -> doCreate(batchNo, req));
    }

    private RiskChecklistResponse doCreate(String batchNo, RiskChecklistCreateRequest req) {
        BatchRow batch = mustLock(batchNo);
        RiskLevel level = parseLevel(req.riskLevel());
        String now = now();
        if (BatchStatus.RELEASED.name().equals(batch.status())) {
            repo.insertLateEvent(batch.id(), "LATE_RISK_CHECKLIST",
                    "核销后迟到风险绑定：等级 " + level.name() + "，规则版本 " + req.ruleVersion(), now);
            log.warn("批次 {} 已出厂核销，风险绑定迟到登记并告警", batchNo);
            return new RiskChecklistResponse(batchNo, true, null);
        }
        if (BatchStatus.DECLARED.name().equals(batch.status())) {
            throw ApiException.unprocessable("宰前检疫合格后才能绑定风险抽检清单");
        }
        if (riskRepo.findCurrentChecklist(batch.id()).isPresent()) {
            throw ApiException.unprocessable("批次已存在当前抽检清单，同一批次只一个当前清单");
        }
        List<String> declaredHeads = declaredHeads(batch.id());
        int listNo = riskRepo.maxListNo(batch.id()) + 1;
        int sampleCount = level.sampleCount(declaredHeads.size());
        riskRepo.insertChecklist(batch.id(), listNo, level.name(), req.ruleVersion(),
                sampleCount, writeHeads(declaredHeads), true, 1, now);
        ChecklistRow created = riskRepo.findChecklist(batch.id(), listNo).orElseThrow();
        for (String headNo : declaredHeads.subList(0, sampleCount)) {
            riskRepo.insertSample(created.id(), headNo);
        }
        return new RiskChecklistResponse(batchNo, false, view(created.id()));
    }

    // ---------- 风险等级变更 ----------

    /**
     * 风险变更：抽检未完成前提高风险等级原子扩充清单并保留既有结果，降低不缩减；
     * 已完成清单不可改，另开补充清单并再次锁出厂；核销后仅记迟到告警。
     */
    @Transactional
    public RiskChecklistResponse changeRisk(String batchNo, RiskChangeRequest req) {
        return idempotency.execute("risk-change", req.requestId(), req,
                RiskChecklistResponse.class, () -> doChangeRisk(batchNo, req));
    }

    private RiskChecklistResponse doChangeRisk(String batchNo, RiskChangeRequest req) {
        BatchRow batch = mustLock(batchNo);
        RiskLevel level = parseLevel(req.riskLevel());
        ChecklistRow current = mustCurrent(batch.id());
        String now = now();
        if (BatchStatus.RELEASED.name().equals(batch.status())) {
            repo.insertLateEvent(batch.id(), "LATE_RISK_CHANGE",
                    "核销后迟到风险变更：等级 " + level.name() + "，规则版本 " + req.ruleVersion()
                            + "，期望版本 " + req.expectedVersion(), now);
            log.warn("批次 {} 已出厂核销，风险变更迟到登记并告警", batchNo);
            return new RiskChecklistResponse(batchNo, true, view(current.id()));
        }
        requireVersion(current, req.expectedVersion());
        RiskLevel currentLevel = RiskLevel.valueOf(current.riskLevel());
        if (level == currentLevel && current.ruleVersion().equals(req.ruleVersion())) {
            throw ApiException.unprocessable("风险等级与规则版本均未变化");
        }
        if (ChecklistStatus.COMPLETED.name().equals(current.status())) {
            // 已完成清单不可改：另开补充清单，再次锁出厂
            riskRepo.clearCurrentFlag(current.id());
            List<String> declaredHeads = declaredHeads(batch.id());
            int listNo = riskRepo.maxListNo(batch.id()) + 1;
            int sampleCount = level.sampleCount(declaredHeads.size());
            riskRepo.insertChecklist(batch.id(), listNo, level.name(), req.ruleVersion(),
                    sampleCount, writeHeads(declaredHeads), true, 1, now);
            ChecklistRow supplementary = riskRepo.findChecklist(batch.id(), listNo).orElseThrow();
            for (String headNo : declaredHeads.subList(0, sampleCount)) {
                riskRepo.insertSample(supplementary.id(), headNo);
            }
            return new RiskChecklistResponse(batchNo, false, view(supplementary.id()));
        }
        // 未完成清单：提高原子扩充并保留既有结果，降低不缩减
        List<SampleRow> existing = riskRepo.findSamples(current.id());
        List<String> declaredHeads = declaredHeads(batch.id());
        int required = level.sampleCount(declaredHeads.size());
        int newCount = Math.max(existing.size(), required);
        if (level.ratioPercent() > currentLevel.ratioPercent() && required > existing.size()) {
            Set<String> present = new LinkedHashSet<>();
            for (SampleRow row : existing) {
                present.add(row.headNo());
            }
            for (String headNo : declaredHeads.subList(0, required)) {
                if (present.add(headNo)) {
                    riskRepo.insertSample(current.id(), headNo);
                }
            }
        }
        int updated = riskRepo.applyRiskChange(current.id(), req.expectedVersion(), level.name(),
                req.ruleVersion(), newCount);
        if (updated == 0) {
            throw ApiException.unprocessable("清单版本冲突：期望 " + req.expectedVersion()
                    + "，当前 " + current.version());
        }
        return new RiskChecklistResponse(batchNo, false, view(current.id()));
    }

    // ---------- 逐只抽检结果 ----------

    /**
     * 提交抽检结果：清单外结果拒绝；重复同结果无新记录、不递增版本；异结果冲突；
     * 任一阳性整批专项隔离；全部样本提交后清单完成。核销后仅记迟到告警。
     */
    @Transactional
    public RiskChecklistResponse submitResult(String batchNo, SampleResultRequest req) {
        return idempotency.execute("risk-result", req.requestId(), req,
                RiskChecklistResponse.class, () -> doSubmitResult(batchNo, req));
    }

    private RiskChecklistResponse doSubmitResult(String batchNo, SampleResultRequest req) {
        BatchRow batch = mustLock(batchNo);
        SampleResult result = parseResult(req.result());
        ChecklistRow current = mustCurrent(batch.id());
        String now = now();
        if (BatchStatus.RELEASED.name().equals(batch.status())) {
            repo.insertLateEvent(batch.id(), "LATE_RISK_RESULT",
                    "核销后迟到抽检结果：头只 " + req.headNo() + "，结果 " + result.name(), now);
            log.warn("批次 {} 已出厂核销，抽检结果迟到登记并告警", batchNo);
            return new RiskChecklistResponse(batchNo, true, view(current.id()));
        }
        requireVersion(current, req.expectedVersion());
        SampleRow sample = riskRepo.findSample(current.id(), req.headNo())
                .orElseThrow(() -> ApiException.unprocessable(
                        "清单外头只，拒绝登记抽检结果：" + req.headNo()));
        if (sample.result() != null) {
            if (sample.result().equals(result.name())) {
                // 重复同结果：无新记录，版本不变
                return new RiskChecklistResponse(batchNo, false, view(current.id()));
            }
            throw ApiException.unprocessable("抽检结果冲突：头只 " + req.headNo()
                    + " 已登记 " + sample.result() + "，拒绝改为 " + result.name());
        }
        riskRepo.setSampleResult(sample.id(), result.name(), now);
        boolean complete = riskRepo.countPendingSamples(current.id()) == 0;
        int updated = riskRepo.advanceAfterResult(current.id(), req.expectedVersion(),
                complete, now);
        if (updated == 0) {
            throw ApiException.unprocessable("清单版本冲突：期望 " + req.expectedVersion()
                    + "，当前 " + current.version());
        }
        if (result == SampleResult.POSITIVE) {
            String reason = "清单 #" + current.listNo() + " 头只 " + req.headNo() + " 抽检阳性";
            repo.markIsolated(batch.id(), reason, now);
            log.warn("批次 {} 进入专项隔离：{}", batchNo, reason);
        }
        return new RiskChecklistResponse(batchNo, false, view(current.id()));
    }

    // ---------- 清单及隔离原因查询 ----------

    /**
     * 批次风险总览：专项隔离状态与原因、全部抽检清单（含冻结编号与逐只结果）。
     */
    @Transactional(readOnly = true)
    public RiskOverviewResponse overview(String batchNo) {
        BatchRow batch = repo.findBatchByNo(batchNo)
                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
        List<ChecklistView> checklists = new ArrayList<>();
        for (ChecklistRow row : riskRepo.findChecklists(batch.id())) {
            checklists.add(view(row.id()));
        }
        return new RiskOverviewResponse(batch.batchNo(), batch.isolated(), batch.isolatedAt(),
                batch.isolationReason(), checklists);
    }

    // ---------- 内部：视图 / 校验 / 工具 ----------

    /** 行锁读取批次：串行化抽检结果、风险变更与出厂核销。 */
    private BatchRow mustLock(String batchNo) {
        return repo.findBatchByNoForUpdate(batchNo)
                .orElseThrow(() -> ApiException.notFound("批次不存在：" + batchNo));
    }

    private ChecklistRow mustCurrent(long batchId) {
        return riskRepo.findCurrentChecklist(batchId)
                .orElseThrow(() -> ApiException.notFound("批次未绑定风险抽检清单"));
    }

    private void requireVersion(ChecklistRow current, int expectedVersion) {
        if (current.version() != expectedVersion) {
            throw ApiException.unprocessable("清单版本冲突：期望 " + expectedVersion
                    + "，当前 " + current.version());
        }
    }

    /** 申报头只集合：按头只编号字典序（String.compareTo）。 */
    private List<String> declaredHeads(long batchId) {
        return repo.findHeads(batchId).stream()
                .map(HeadRow::headNo)
                .sorted()
                .toList();
    }

    private ChecklistView view(long checklistId) {
        ChecklistRow row = riskRepo.findChecklistById(checklistId).orElseThrow();
        List<ChecklistView.SampleView> samples = riskRepo.findSamples(checklistId).stream()
                .map(s -> new ChecklistView.SampleView(s.headNo(), s.result(), s.resultAt()))
                .toList();
        return new ChecklistView(row.listNo(), row.riskLevel(), row.ruleVersion(),
                row.sampleCount(), row.status(), row.current(), row.version(),
                row.createdAt(), row.completedAt(), readHeads(row.declaredHeads()), samples);
    }

    @SuppressWarnings("unchecked")
    private List<String> readHeads(String json) {
        try {
            return objectMapper.readValue(json, List.class);
        } catch (Exception e) {
            throw new IllegalStateException("冻结申报头只集合反序列化失败", e);
        }
    }

    private RiskLevel parseLevel(String riskLevel) {
        try {
            return RiskLevel.valueOf(riskLevel);
        } catch (Exception e) {
            throw ApiException.badRequest("未知风险等级：" + riskLevel + "，支持 NORMAL/STRICT");
        }
    }

    private SampleResult parseResult(String result) {
        try {
            return SampleResult.valueOf(result);
        } catch (Exception e) {
            throw ApiException.badRequest("未知抽检结果：" + result + "，支持 NEGATIVE/POSITIVE");
        }
    }

    private String writeHeads(List<String> headNos) {
        try {
            return objectMapper.writeValueAsString(headNos);
        } catch (Exception e) {
            throw new IllegalStateException("申报头只集合序列化失败", e);
        }
    }

    private String now() {
        return Instant.now(clock).toString();
    }
}
